fn frame(t: i32) {
    let tab = [0, 49, 90, 117, 127, 117, 90, 49, 0, -49, -90, -117, -127, -117, -90, -49];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2 - 10;
    let r: i32 = if w < h { w / 4 } else { h / 4 };
    host::display::clear(0x000000);
    let lead: i32 = (t / 3) & 15;
    let mut k: i32 = 0;
    while k < 16 {
        let d: i32 = (lead - k + 16) & 15;
        let g: i32 = 255 - d * 15;
        let x: i32 = cx + tab[k] * r / 127;
        let y: i32 = cy + tab[(k + 4) & 15] * r / 127;
        host::display::fill_rect(x - 3, y - 3, 6, 6, g * 65536 + g * 256 + g);
        k = k + 1;
    }
    host::display::draw_string(cx - 28, cy + r + 16, "LOADING", 0x808080, 1);
    host::display::present();
}
